tools.example:
{
  "type": "EAGLE CAM job", "version": "9.2.0", "units": "metric", "output_type": "directory",
  "description": {"EN": "Company 2 layer job"},
  "outputs": [
    {"output_type": "gerber", "version": "RS274X", "filename_prefix": "CAMOutputs/GerberFiles",
     "format_specifier": {"integer": 3, "decimal": 4}, "generate_job_file": true,
     "outputs": [{"type": "gerber_layer", "name": "Top Copper", "layers": [1, 17, 18],
                  "filename_format": "%PREFIX/copper_top.gbr", "polarity": "positive",
                  "config": {"file_function": "Copper", "layer": 1, "layer_type": "top", "layer_details": "mixed"}}]},
    {"output_type": "drill", "filename_prefix": "CAMOutputs/DrillFiles", "format_specifier": {"integer": 3, "decimal": 3},
     "outputs": [{"type": "autodrills", "name": "Auto Drill", "filename_format": "%DRILLPREFIX/drill_%FROM_%TO.xln"}]}
  ]
}

"config": {"file_function": "Copper", "layer": 2, "layer_type": "Inner", "layer_details": "mixed"}
"config": {"file_function": "Profile", "plating": "non-plated"}
"config": {"file_function": "Other", "description": "Top Copper"}

GRID MM;
CHANGE LAYER TOP;
POLYGON _OUTLINES_ 0.2 (-1 -1) (101 -1) (101 81) (-1 81) (-1 -1);
CHANGE RANK 6 (-1 -1);
RATSNEST;
RUN outlines HPGL 0.2 1 D:/out/board_top.plt;   # device Script|HPGL, width in mm, layer 1..16 (0 = active)
